import java.util.*;

class Solution {
  public List<String> findStrobogrammatic(int n) {
    return build(n, n);
  }

  // all strobogrammatic strings of length len; leading zeros only allowed below the full length
  private List<String> build(int len, int total) {
    if (len == 0) return new ArrayList<>(Collections.singletonList(""));
    if (len == 1) return new ArrayList<>(Arrays.asList("0", "1", "8"));
    List<String> res = new ArrayList<>();
    for (String mid : build(len - 2, total)) {
      if (len != total) res.add("0" + mid + "0");
      res.add("1" + mid + "1");
      res.add("8" + mid + "8");
      res.add("6" + mid + "9");
      res.add("9" + mid + "6");
    }
    return res;
  }
}
